using UnityEngine;
using UnityEngine.InputSystem;
namespace LWS.TruckBilliards {
public enum BilliardsMode {SinglePlayer,SharedKeyboard,SeparateControllers,HotSeat,Practice,AIVsAI,Custom}
public enum BilliardsControl {KeyboardWASD,KeyboardArrows,Gamepad,AI}
public enum BilliardsScreen {Main,Setup,Join,Match,Help,Settings,Pause,Confirm,Handoff,Disconnect,Result,GroupSelection}
[System.Serializable]public sealed class BilliardsPlayerSlot : LWS.TruckSports.ISportsParticipantSlot {
 public string participantId;
 string LWS.TruckSports.ISportsParticipantSlot.ParticipantId {get=>participantId;set=>participantId=value;}
 string LWS.TruckSports.ISportsParticipantSlot.DisplayName {get=>name;set=>name=value;}
 Color LWS.TruckSports.ISportsParticipantSlot.ParticipantColor {get=>color;set=>color=value;}
 bool LWS.TruckSports.ISportsParticipantSlot.IsBot=>control==BilliardsControl.AI;

 public string name="Player";public Color color=Color.cyan;public BilliardsTruck truck;public BilliardsDifficulty difficulty=BilliardsDifficulty.Normal;
 public int Group=>truck!=null&&truck.match!=null?truck.match.rules.Group(truck.side):0;
 public BilliardsControl control;[System.NonSerialized]public Gamepad pad;[System.NonSerialized]public bool released;
}
public sealed class BilliardsSession:MonoBehaviour {
 LWS.TruckSports.SportsParticipantBinding participantBinding;string participantMatchId;
 public void RefreshParticipants(bool saveEdits=false){if(participantBinding==null||!participantBinding.Matches(players))participantBinding=new LWS.TruckSports.SportsParticipantBinding(players);else participantBinding.Refresh(saveEdits);}
 void RecordParticipants(string summary,int count){LWS.TruckSports.SportsParticipantRegistry.Record(participantMatchId,SetupKey,summary,players,count);}

 public BilliardsMatch match;public BilliardsInputRouter input;public BilliardsMenus menus;public BilliardsSettings settings;public BilliardsHUD hud;
 public BilliardsPlayerSlot[] players=new BilliardsPlayerSlot[2];public BilliardsAI[] agents;
 public BilliardsMode mode;public int breakChoice,openingBreaker,sharedOwner;public bool HandoffPending{get;private set;}
 public BilliardsFormat format;public BilliardsDifficulty difficulty=BilliardsDifficulty.Normal;public readonly BilliardsSeries series=new BilliardsSeries();public BilliardsFeedback feedback;public BilliardsCelebration celebration;
 public bool IsPractice=>mode==BilliardsMode.Practice;public bool OnePadMode=>(mode==BilliardsMode.HotSeat||IsPractice)&&hotSeatGamepad;
 public bool hotSeatGamepad;public bool InMatch{get;private set;}
 public BilliardsScreen Screen{get;private set;}=BilliardsScreen.Main;public BilliardsScreen BackScreen{get;private set;}=BilliardsScreen.Main;
 public string Message{get;private set;}="";public bool GameplayEnabled=>InMatch&&Screen==BilliardsScreen.Match;
 public bool IsAI(int side)=>!IsPractice&&players[side].control==BilliardsControl.AI;
 public bool AIOnly=>!IsPractice&&IsAI(0)&&IsAI(1);
 public BilliardsDifficulty DifficultyFor(int side)=>mode==BilliardsMode.SinglePlayer&&side==1?difficulty:players[side].difficulty;
 public bool BothPadsReady=>Ready(0)&&Ready(1)&&players[0].pad!=players[1].pad;
 public bool Ready(int side)=>players[side].pad!=null&&players[side].pad.added&&players[side].pad.enabled;
 public Gamepad SharedPad=>players[0].pad;bool rulesEnded=>match.rules.Phase==MatchPhase.Ended;float resultDelay,choiceDelay;
 readonly System.Collections.Generic.HashSet<Material> paints=new System.Collections.Generic.HashSet<Material>();
 void Awake(){players[0].truck=match.player;players[1].truck=match.ai;match.session=this;input.session=this;settings.session=this;agents=new BilliardsAI[2];for(int i=0;i<2;i++){agents[i]=players[i].truck.GetComponent<BilliardsAI>();if(agents[i]==null&&i==1)agents[i]=match.opponent;if(agents[i]==null)agents[i]=players[i].truck.gameObject.AddComponent<BilliardsAI>();agents[i].match=match;agents[i].truck=players[i].truck;agents[i].enabled=false;}}
 void Start(){settings.Load();if(!LoadSetup())SelectMode(mode);RefreshParticipants();Show(LWS.TruckSports.SportsNavigation.Collection?BilliardsScreen.Setup:BilliardsScreen.Main);}
 public void Show(BilliardsScreen screen){bool changed=Screen!=screen;Screen=screen;Time.timeScale=GameplayEnabled?1:0;if(changed||screen!=BilliardsScreen.Match)input.GateAll();if(feedback!=null){feedback.StopMotors();if(screen!=BilliardsScreen.Match)feedback.StopAudio();}if(celebration!=null&&screen!=BilliardsScreen.Result)celebration.Clear();menus?.Show(screen);hud?.Refresh();}
 public void SelectMode(BilliardsMode value){mode=value;if(value!=BilliardsMode.Custom){players[0].control=BilliardsControl.KeyboardWASD;players[1].control=value==BilliardsMode.SinglePlayer||value==BilliardsMode.AIVsAI?BilliardsControl.AI:BilliardsControl.KeyboardArrows;if(value==BilliardsMode.AIVsAI)players[0].control=BilliardsControl.AI;if(value==BilliardsMode.SeparateControllers)players[0].control=players[1].control=BilliardsControl.Gamepad;if(value==BilliardsMode.HotSeat)players[1].control=BilliardsControl.KeyboardWASD;if(value==BilliardsMode.Practice)players[0].control=hotSeatGamepad?BilliardsControl.Gamepad:BilliardsControl.KeyboardWASD;}if(value==BilliardsMode.SeparateControllers&&players[0].pad==players[1].pad)players[1].pad=null;Message="";menus?.RefreshSetup();}
 public void CycleParticipant(int side){mode=BilliardsMode.Custom;players[side].control=(BilliardsControl)(((int)players[side].control+1)%4);if(!IsAI(side)&&players[0].control==players[1].control&&players[side].control!=BilliardsControl.Gamepad)players[side].control=players[1-side].control==BilliardsControl.KeyboardWASD?BilliardsControl.KeyboardArrows:BilliardsControl.KeyboardWASD;SaveSetup();menus.RefreshSetup();}
 public bool DevicesAvailable(){if(AIOnly)return true;if(mode!=BilliardsMode.HotSeat&&!IsPractice&&!IsAI(0)&&!IsAI(1)&&players[0].control==players[1].control&&players[0].control!=BilliardsControl.Gamepad)return false;if(OnePadMode)return Ready(0);for(int i=0;i<(IsPractice?1:2);i++){if(IsAI(i))continue;if(players[i].control==BilliardsControl.Gamepad){if(!Ready(i))return false;}else if(Keyboard.current==null||!Keyboard.current.enabled)return false;}return mode==BilliardsMode.HotSeat||IsPractice||players[0].control!=BilliardsControl.Gamepad||players[1].control!=BilliardsControl.Gamepad||players[0].pad!=players[1].pad;}
 public bool StartMatch(){if(mode==BilliardsMode.HotSeat){players[0].control=players[1].control=hotSeatGamepad?BilliardsControl.Gamepad:BilliardsControl.KeyboardWASD;players[1].pad=hotSeatGamepad?players[0].pad:null;}if(IsPractice){players[0].control=hotSeatGamepad?BilliardsControl.Gamepad:BilliardsControl.KeyboardWASD;players[1].control=BilliardsControl.KeyboardArrows;players[1].pad=null;}if(!DevicesAvailable()){Message="Assign every human's required input before starting.";Show(BilliardsScreen.Join);return false;}SaveSetup();participantMatchId=System.Guid.NewGuid().ToString("N");HandoffPending=false;openingBreaker=IsPractice?0:breakChoice==2?Random.Range(0,2):breakChoice;series.Start(IsPractice?BilliardsFormat.SingleRack:format,openingBreaker);InMatch=true;match.FreshMatch(openingBreaker);sharedOwner=openingBreaker;ApplyIdentity();Show(BilliardsScreen.Match);return true;}
 public void Rematch(){if(!series.Finished||!rulesEnded)return;if(!DevicesAvailable()){Disconnect();return;}participantMatchId=System.Guid.NewGuid().ToString("N");series.Start(format,1-series.OriginalBreaker);BeginRack(true);}
 public void Restart()=>RestartRack();public void RestartRack(){if(!IsPractice&&(rulesEnded||series.RackFinished))return;BeginRack(true);}
 public void RestartSeries(){series.Start(format,series.OriginalBreaker);BeginRack(true);}
 public void NextRack(){if(!DevicesAvailable()){Disconnect();return;}if(series.Next())BeginRack(true);}
 void BeginRack(bool readiness){HandoffPending=false;openingBreaker=IsPractice?0:series.Breaker;match.FreshMatch(openingBreaker);ApplyIdentity();if(readiness&&mode==BilliardsMode.HotSeat&&sharedOwner!=openingBreaker){HandoffPending=true;Show(BilliardsScreen.Handoff);}else{sharedOwner=openingBreaker;Show(BilliardsScreen.Match);}}
 public void RepositionCue(){if(!IsPractice||!match.AreSettled||!match.rules.PracticePlacement())return;Show(BilliardsScreen.Match);input.BeginPlacement();}
 public string ScoreText=>IsPractice?"PRACTICE • ONE TRUCK • NO OPPONENT":Name(0)+"  "+series.Wins[0]+" : "+series.Wins[1]+"  "+Name(1)+"   •   RACK "+series.RackNumber+"   •   FIRST TO "+series.Required;
 public void MainMenu(){SaveSetup();HandoffPending=false;InMatch=false;foreach(var a in agents){a.enabled=false;a.ResetPlan();}match.HidePlacement();match.player.Stop();match.ai.Stop();if(LWS.TruckSports.SportsNavigation.Collection){feedback?.StopAudio();LWS.TruckSports.SportsNavigation.FrontEnd();return;}match.FreshMatch(0);match.ai.gameObject.SetActive(true);Show(BilliardsScreen.Main);}
 public void ApplyIdentity(){for(int i=0;i<2;i++){players[i].name=string.IsNullOrWhiteSpace(players[i].name)?"Player "+(i+1):players[i].name.Trim();var label=players[i].truck.transform.Find("Truck label");if(label!=null){var text=label.GetComponent<TextMesh>();text.text=Name(i);text.color=players[i].color;}foreach(var renderer in players[i].truck.GetComponentsInChildren<MeshRenderer>())if(renderer.name=="Chassis"||renderer.name=="Colored front bumper")foreach(var material in renderer.materials){paints.Add(material);material.color=players[i].color;}agents[i].enabled=IsAI(i);agents[i].ResetPlan();}match.ai.gameObject.SetActive(!IsPractice);}
 public string Name(int side)=>players[side].name;
 public void ResetAIPlans(){if(agents!=null)foreach(var a in agents)if(a!=null&&IsAI(a.truck.side))a.ResetPlan();}
 public void ShotResolved(int previousTurn){ResetAIPlans();foreach(var p in players)p.truck.Disarm();if(match.rules.Phase==MatchPhase.Ended){if(series.Award(match.rules.Winner)){if(series.Finished)RecordParticipants("Winner: "+Name(match.rules.Winner),IsPractice?1:2);resultDelay=0;Show(BilliardsScreen.Result);feedback?.Cue(series.Finished&&series.Required>1?BilliardsSound.SeriesWin:BilliardsSound.RackWin);feedback?.Pulse(match.rules.Winner,series.Finished?.38f:.23f,.3f);celebration?.Play(players[match.rules.Winner].color,series.Finished&&series.Required>1);}return;}if(match.rules.Phase==MatchPhase.GroupSelection){choiceDelay=0;Show(BilliardsScreen.GroupSelection);}else if(mode==BilliardsMode.HotSeat&&previousTurn!=match.rules.Turn){HandoffPending=true;Message="PASS TO "+Name(match.rules.Turn);Show(BilliardsScreen.Handoff);}else if(match.rules.Phase==MatchPhase.Placement)input.BeginPlacement();if(feedback!=null){if(match.rules.LastFoul)feedback.Cue(BilliardsSound.Foul);else if(previousTurn!=match.rules.Turn)feedback.Cue(BilliardsSound.Turn);if(match.rules.LastScored&&!match.rules.LastFoul)feedback.Pulse(previousTurn,.16f,.14f);}}
 public bool ChooseGroup(int side,int group){if(!match.rules.ChooseGroup(side,group))return false;ResetAIPlans();Show(BilliardsScreen.Match);return true;}
 int AIGroup(){int solids=match.rules.RemainingGroup(1),stripes=match.rules.RemainingGroup(2);if(solids!=stripes)return solids<stripes?1:2;float a=float.PositiveInfinity,b=float.PositiveInfinity;foreach(var ball in match.balls)if(!ball.Pocketed){float distance=Vector3.Distance(ball.body.position,match.balls[0].body.position);if(BilliardsRules.BallGroup(ball.number)==1)a=Mathf.Min(a,distance);if(BilliardsRules.BallGroup(ball.number)==2)b=Mathf.Min(b,distance);}return a<=b?1:2;}
 void Update(){if(Screen==BilliardsScreen.Result&&AIOnly&&!series.Finished){resultDelay+=Time.unscaledDeltaTime;if(resultDelay>=2.5f)NextRack();}if(Screen==BilliardsScreen.GroupSelection&&IsAI(match.rules.Turn)){choiceDelay+=Time.unscaledDeltaTime;if(choiceDelay>=.8f)ChooseGroup(match.rules.Turn,AIGroup());}}
 public void ConfirmHandoff(){if(Screen!=BilliardsScreen.Handoff)return;HandoffPending=false;sharedOwner=match.rules.Turn;Show(BilliardsScreen.Match);if(match.rules.Phase==MatchPhase.Placement)input.BeginPlacement();}
 public void Pause(){if(!InMatch||Screen==BilliardsScreen.Pause||Screen==BilliardsScreen.Disconnect||Screen==BilliardsScreen.Result)return;BackScreen=Screen;Show(BilliardsScreen.Pause);}
 public void Resume(){if(!DevicesAvailable()){Disconnect();return;}Show(!IsPractice&&series.RackFinished?BilliardsScreen.Result:HandoffPending?BilliardsScreen.Handoff:match.rules.Phase==MatchPhase.GroupSelection?BilliardsScreen.GroupSelection:BilliardsScreen.Match);}
 public void Disconnect(){if(Screen!=BilliardsScreen.Disconnect)BackScreen=Screen==BilliardsScreen.Pause?BackScreen:Screen;Message="Assigned input unavailable: ";for(int i=0;i<2;i++)if(!IsAI(i)&&(players[i].control==BilliardsControl.Gamepad?!Ready(i):Keyboard.current==null||!Keyboard.current.enabled))Message+=Name(i)+" ";Show(BilliardsScreen.Disconnect);}
 public bool Assign(int side,Gamepad pad){if(mode==BilliardsMode.HotSeat||IsPractice)side=0;if(pad==null||!pad.added||!pad.enabled)return false;if(mode!=BilliardsMode.HotSeat&&!IsPractice&&!IsAI(1-side)&&players[1-side].control==BilliardsControl.Gamepad&&players[1-side].pad==pad)return false;players[side].pad=pad;if(mode==BilliardsMode.HotSeat)players[1].pad=pad;input.GateAll();menus?.RefreshJoin();return true;}
 public void Reassign(int side){if(mode==BilliardsMode.HotSeat||IsPractice)side=0;players[side].pad=null;if(mode==BilliardsMode.HotSeat)players[1].pad=null;menus?.RefreshJoin();}
 public string Bindings(int side,bool placement=false){if(IsAI(side))return "AI "+DifficultyFor(side)+" • automatic shots, placement and group choice.";bool pad=players[side].control==BilliardsControl.Gamepad||(mode==BilliardsMode.HotSeat&&hotSeatGamepad);if(pad)return placement?"Left stick: place • South: confirm":"Left stick: steer • RT: accelerate • LT: reverse\nSouth: brake • North: reset • Start: pause";if(mode==BilliardsMode.SinglePlayer&&!placement)return "WASD or arrows: drive • Space: brake • R: reset • Esc: pause";bool second=mode!=BilliardsMode.HotSeat&&!IsPractice&&players[side].control==BilliardsControl.KeyboardArrows;return second?placement?"Arrows: place • Right Ctrl: confirm":"Arrows: drive • Right Shift: brake • Enter: reset • Esc: pause":placement?"WASD / mouse: place • F / click: confirm":"WASD: drive • Space: brake • R: reset • Esc: pause";}
 [System.Serializable]sealed class SlotData{public string name,participantId;public Color color;public BilliardsControl control;public BilliardsDifficulty difficulty;public int padId;}
 [System.Serializable]sealed class SetupData{public BilliardsMode mode;public BilliardsFormat format;public int breakChoice;public bool hotSeatGamepad;public SlotData[] slots;}
 public const string SetupKey="TruckBilliards.Setup.v2";
 public void SaveSetup(){RefreshParticipants(true);var d=new SetupData{mode=mode,format=format,breakChoice=breakChoice,hotSeatGamepad=hotSeatGamepad,slots=new SlotData[2]};for(int i=0;i<2;i++)d.slots[i]=new SlotData{participantId=players[i].participantId,name=players[i].name,color=players[i].color,control=players[i].control,difficulty=DifficultyFor(i),padId=players[i].pad?.deviceId??-1};LWS.TruckSports.SportsPrefs.SetString(SetupKey,JsonUtility.ToJson(d));LWS.TruckSports.SportsPrefs.Save();}
 bool LoadSetup(){if(!LWS.TruckSports.SportsPrefs.HasKey(SetupKey))return false;try{var d=JsonUtility.FromJson<SetupData>(LWS.TruckSports.SportsPrefs.GetString(SetupKey));if(d==null||d.slots==null||d.slots.Length!=2)return false;mode=d.mode;format=d.format;breakChoice=Mathf.Clamp(d.breakChoice,0,2);hotSeatGamepad=d.hotSeatGamepad;for(int i=0;i<2;i++){players[i].participantId=d.slots[i].participantId;players[i].name=d.slots[i].name;players[i].color=d.slots[i].color;players[i].control=d.slots[i].control;players[i].difficulty=d.slots[i].difficulty;players[i].pad=InputSystem.GetDeviceById(d.slots[i].padId) as Gamepad;}if(mode==BilliardsMode.SinglePlayer)difficulty=players[1].difficulty;return true;}catch(System.Exception){return false;}}
 void OnDestroy(){foreach(var m in paints)if(m!=null)Destroy(m);Time.timeScale=1;}
}
}